using System;

// PROGRAM: Memahami Top-Level Statements dan Argumen CLI
Console.WriteLine("=== PROGRAM BERJALAN ===");

// Menampilkan argumen baris perintah (secara otomatis tersedia via variabel 'args')
Console.WriteLine($"Jumlah Argumen Diterima: {args.Length}");
for (int i = 0; i < args.Length; i++)
{
    Console.WriteLine($"  Argumen [{i}]: {args[i]}");
}

// Menggunakan tipe yang dideklarasikan di bawah (mematuhi CS8803)
var invoice = new Invoice("INV-001", 1_500_000m);
Console.WriteLine($"Invoice dibuat: {invoice.Number} sebesar Rp {invoice.Total:N0}");

// DEKLARASI TIPE WAJIB DI BAWAH TOP-LEVEL STATEMENTS
record Invoice(string Number, decimal Total);

