using System;

public class LogFormatter
{
    public static string FormatStartupLog(string? environment, string? serviceName, int argCount)
    {
        string env = string.IsNullOrWhiteSpace(environment) ? "DEVELOPMENT" : environment.Trim().ToUpperInvariant();
        string name = string.IsNullOrWhiteSpace(serviceName) ? "CORE-API" : serviceName.Trim();

        return $"[ENV:{env}] Service {name} initialized with {argCount} arguments.";
    }

    public static void Main()
    {
        Console.WriteLine(FormatStartupLog("Production", "PaymentService", 2));
    }
}
